const CACHE='almeida-catalogo-v53';
const FILES=['./','index.html','conta.html','conta.js','account-dashboard.css','produto.html','admin.html','style.css','site.js','admin.js','auth-storefront.js','account-nav.js','account-wallet.js','cart-cashback.js','pricing-admin.js','pricing-storefront.js','admin-orders.js','admin-customers.js','admin-sections.js','promotion-filter.js','pwa-install.js','manifest.webmanifest','produto.js','product-details.js','image-cleanup.js','product-images.js','catalogo.js','supabase-config.js','assets/logo.jpg','assets/pwa-icon-192.png','assets/pwa-icon-512.png','assets/fachada-almeida.png','style.css?v=28','account-dashboard.css?v=3','site.js?v=24','pricing-storefront.js?v=10','auth-storefront.js?v=9','account-nav.js?v=1','account-wallet.js?v=4','conta.js?v=5','produto.js?v=27','product-details.js?v=1','image-cleanup.js?v=16','product-images.js?v=16','admin.js?v=31','pricing-admin.js?v=2','admin-orders.js?v=6','admin-customers.js?v=2','admin-sections.js?v=1','promotion-filter.js?v=2','pwa-install.js?v=1'];
self.addEventListener('install',event=>{self.skipWaiting();event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)))});
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method==='GET'&&new URL(event.request.url).origin===location.origin)event.respondWith(fetch(event.request).then(response=>{const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));return response}).catch(()=>caches.match(event.request)))});

